class Resource extends Base {
  mount(){
    this.items??=[{label:'Studio',symbol:'◈'},{label:'Explore',symbol:'⌕'},{label:'Projects',symbol:'▤'},{label:'Library',symbol:'✳'},{label:'Messages',symbol:'✉'},{label:'Settings',symbol:'⚙'}];this.selected=0;
    this.render(`<section class="scene"><div class="caption"><span class="label">A SMALL SPACE FOR BIG IDEAS</span><h2>Everything, within reach.</h2><p class="hint">Choose where you want to go.</p></div><div class="workspace"><div class="workspace-icon">◈</div><span class="label">YOUR WORKSPACE</span><h3>Studio</h3><p>Start with a little curiosity.</p></div><nav aria-label="Workspace navigation">${this.items.map((item,i)=>`<button data-index="${i}" aria-label="${escape(item.label)}" aria-pressed="${i===0}"><span>${escape(item.symbol)}</span><small>${escape(item.label)}</small><i></i></button>`).join('')}</nav><span class="bottom-note">PROXIMITY / INERTIA / FOCUS</span></section>`,`.scene{min-height:500px;background:radial-gradient(ellipse at 50% 65%,#48584935,transparent 60%),var(--bg);border:1px solid var(--line);border-radius:var(--radius);padding:38px 20px 24px;display:flex;flex-direction:column;align-items:center;gap:28px;text-align:center}.caption h2{font-size:clamp(24px,4vw,37px);font-weight:500;letter-spacing:-1.4px;margin:10px 0}.workspace{display:flex;flex-direction:column;align-items:center;gap:8px}.workspace-icon{font-size:35px;width:70px;height:70px;border:1px solid #c6e6b044;border-radius:22px;color:var(--accent);background:#c6e6b008;margin:5px 0 9px}.workspace h3{font-size:22px;font-weight:500}.workspace p{font-size:12px;color:var(--muted)}nav{display:flex;align-items:flex-end;gap:10px;padding:16px 16px 22px;background:color-mix(in srgb,var(--panel) 90%,transparent);border:1px solid var(--line);border-radius:22px;box-shadow:0 15px 50px #0003;min-height:105px;margin-top:8px}nav button{position:relative;display:flex;align-items:center;justify-content:center;width:46px;height:46px;border:1px solid var(--line);background:var(--bg);border-radius:14px;transform-origin:50% 100%;will-change:transform}nav button>span{font-size:23px;color:var(--accent)}nav small{position:absolute;bottom:calc(100% + 14px);padding:5px 8px;background:var(--ink);color:var(--bg);font-size:10px;white-space:nowrap;border-radius:5px;opacity:0;pointer-events:none}nav button:hover small,nav button:focus-visible small{opacity:1}nav i{width:4px;height:4px;border-radius:50%;position:absolute;bottom:-11px;background:transparent}nav [aria-pressed=true] i{background:var(--accent)}.bottom-note{font-size:8px;letter-spacing:2px;color:var(--muted)}@media(max-width:480px){nav{gap:7px;padding:15px 9px 22px}nav button{width:35px;height:38px;border-radius:11px}.scene{min-height:480px}}`);
    this.pointer=null;this.scales=this.items.map(()=>1);const nav=this.$('nav');
    this.listen(nav,'pointermove',e=>{this.pointer=e.clientX;});this.listen(nav,'pointerleave',()=>this.pointer=null);
    this.listen(nav,'focusin',e=>{this.focused=Number(e.target.closest('button')?.dataset.index);});this.listen(nav,'focusout',()=>this.focused=null);
    this.listen(nav,'click',e=>{const button=e.target.closest('button');if(button)this.select(Number(button.dataset.index));});
    this.listen(nav,'keydown',e=>{const buttons=this.$$('nav button');let index=buttons.indexOf(this.shadowRoot.activeElement);if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();index=e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[index].focus();}});
    this.animate(dt=>{this.$$('nav button').forEach((button,i)=>{const box=button.getBoundingClientRect();const distance=this.pointer===null?Infinity:Math.abs(this.pointer-(box.left+box.width/2));const gain=this.number('strength',1.7,1.1,2.4)-1;const target=this.reduced?1:1+gain*Math.exp(-distance*distance/7000)+(this.focused===i?.18:0);this.scales[i]+=(target-this.scales[i])*(1-Math.exp(-dt*(1600/this.number('duration',400,150,900))));button.style.transform=`translateY(${-(this.scales[i]-1)*9}px) scale(${this.scales[i]})`;});});
  }
  select(index){if(!this.items[index])return;this.selected=index;this.$('h3').textContent=this.items[index].label;this.$('.workspace-icon').textContent=this.items[index].symbol;this.$$('nav button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));this.emit('dock-change',{index,label:this.items[index].label});}
}
